mapper.select:
SELECT ctp.* FROM customer_type_price ctp WHERE ctp.deleted = FALSE AND ctp.customer_type_id = #{query.customerTypeId} AND ctp.sku_id = #{query.skuId}
AND (CAST(ctp.sku_id AS TEXT) ILIKE CONCAT('%', #{query.keyword}, '%') OR EXISTS (SELECT 1 FROM customer_type ct WHERE ct.id = ctp.customer_type_id AND ct.deleted = FALSE AND (ct.type_code ILIKE CONCAT('%', #{query.keyword}, '%') OR ct.name ILIKE CONCAT('%', #{query.keyword}, '%'))) OR EXISTS (SELECT 1 FROM product_sku sku JOIN product_spu spu ON spu.id = sku.spu_id AND spu.deleted = FALSE WHERE sku.id = ctp.sku_id AND sku.deleted = FALSE AND (sku.sku_code ILIKE CONCAT('%', #{query.keyword}, '%') OR spu.name ILIKE CONCAT('%', #{query.keyword}, '%'))))
ORDER BY ctp.effective_from DESC, ctp.id DESC
